<?php
declare(strict_types=1);header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: no-referrer');$configPath=__DIR__.'/config.php';if(!is_file($configPath)){http_response_code(503);exit('2Pair server not configured.');}$config=require$configPath;function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function valid_code(string $v):bool{return preg_match('/^[0-9a-f]{32}$/',$v)===1;}$message=$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$code=strtolower(trim((string)($_POST['code']??'')));if(!valid_code($code))$error='Kodas turi būti 32 šešioliktainių simbolių.';else{try{$pdo=new PDO((string)$config['db']['dsn'],(string)$config['db']['user'],(string)$config['db']['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$hash=hash('sha256',$code);$pdo->beginTransaction();$st=$pdo->prepare('SELECT id FROM tp_integrated_sessions WHERE deletion_token_hash=? FOR UPDATE');$st->execute([$hash]);$row=$st->fetch();if(!$row){$pdo->rollBack();$error='Aktyvios sesijos pagal šį kodą nerasta.';}else{$id=(int)$row['id'];$pdo->prepare('DELETE FROM tp_integrated_reflections WHERE session_id=?')->execute([$id]);$pdo->prepare('DELETE e FROM tp_integrated_pair_events e JOIN tp_integrated_blocks b ON b.id=e.block_id WHERE b.session_id=?')->execute([$id]);$pdo->prepare('DELETE a FROM tp_integrated_attempts a JOIN tp_integrated_blocks b ON b.id=a.block_id WHERE b.session_id=?')->execute([$id]);$pdo->prepare('DELETE FROM tp_integrated_blocks WHERE session_id=?')->execute([$id]);$del=$pdo->prepare('DELETE FROM tp_integrated_sessions WHERE id=? AND deletion_token_hash=?');$del->execute([$id,$hash]);if($del->rowCount()!==1)throw new RuntimeException('delete failed');$pdo->commit();$message='Sesijos duomenys ištrinti.';}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('2Pair self-delete error: '.$e->getMessage());$error='Ištrynimas nepavyko.';}}}?><!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>2Pair · duomenų ištrynimas</title><style>body{font-family:system-ui;background:#0c0c0f;color:#eee;margin:0;padding:20px}.card{max-width:520px;margin:8vh auto;background:#17171b;border:1px solid #303038;border-radius:16px;padding:20px}input,button{width:100%;box-sizing:border-box;font:inherit;padding:12px;margin-top:10px;border-radius:10px;background:#111;color:#eee;border:1px solid #444}button{background:#8fc7ae;color:#07100c;font-weight:700}.ok{color:#9fd0b8}.err{color:#e8a5a5}.muted{color:#aaa}</style></head><body><div class="card"><h1>2Pair sesijos duomenų ištrynimas</h1><p class="muted">Įvesk 32 simbolių kodą, kurį gavai po tyrimo duomenų įkėlimo. Kodas serveryje saugomas tik SHA-256 hash forma.</p><?php if($message):?><p class="ok"><?=h($message)?></p><?php endif;?><?php if($error):?><p class="err"><?=h($error)?></p><?php endif;?><form method="post"><input type="text" name="code" minlength="32" maxlength="32" pattern="[0-9a-fA-F]{32}" autocomplete="off" required><button>Ištrinti mano sesiją</button></form></div></body></html>
